    /// Returns whether this decision tree can reach a `Fail` node at runtime,
    /// meaning the pattern it was compiled from is not guaranteed to match. A
    /// tree that cannot fail always succeeds and its bound variables can be
    /// emitted using a combined declaration-and-initialisation.
    ///
    pub fn can_fail(&self) -> bool {
        match self {
            Decision::Fail => true,
            Decision::Run { .. } => false,
            Decision::Guard { if_false, .. } => if_false.can_fail(),
            Decision::Switch {
                choices, fallback, ..
